    {
        CPlayer& player = PlayerManager->GetMainPlayer();
        player.ResetModes();
        CThingPlayerCreature* creature = player.GetPControlledCreature();
        if (IS_THING_ALIVE(creature))
            creature->Kill(false);
        GetThingManager().UpdateDeaths();
    }
